const cache = new Map();
const cacheFor = (seconds) => (req, res, next) => {
  const hit = cache.get(req.originalUrl);
  if (hit && hit.expires > Date.now()) return res.json(hit.body);
  const send = res.json.bind(res);
  res.json = (body) => {
    cache.set(req.originalUrl, { body, expires: Date.now() + seconds * 1000 });
    return send(body);
  };
  next();
};
